// Parse & normalize the DrSnip custom-app Consultation payload.
// Keep the full submission body in submission_full for the PDF generator.
const raw = $input.first().json;
const body = raw.body || raw;
const patient = body.patient || {};
const phone = patient.phone || '';
const phoneDigits = phone.replace(/\D/g, '');

return [{ json: {
  submission_id: body.submissionId || '',
  patient_id_ref: body.patientId || '',
  form_type: body.formType || 'consultation',
  timestamp: body.submittedAt || new Date().toISOString(),
  source: 'custom-app-v2-consultation',

  first_name: (patient.firstName || '').trim(),
  last_name: (patient.lastName || '').trim(),
  email: (patient.email || '').toLowerCase().trim(),
  phone,
  phone_digits: phoneDigits,
  dob: patient.dateOfBirth || '',

  submission_full: body
}}];

// Strict patient match. DrChrono returns candidates by name only; we require
// DOB + email + phone all to match exactly. 0 matches OR >1 matches => manual
// review (NOT a silent no-op as in the original Consultation workflow).
const searchResp = $input.first().json;
const candidates = (searchResp && searchResp.results) || [];
const original = $('Parse & Normalize').first().json;

const wantedDob = (original.dob || '').trim();
const wantedEmail = (original.email || '').toLowerCase().trim();
const wantedPhone = original.phone_digits || '';
const normPhone = (p) => (p || '').replace(/\D/g, '');

const passing = [];
const scored = candidates.map((c) => {
  const cDob = (c.date_of_birth || '').trim();
  const cEmail = (c.email || '').toLowerCase().trim();
  const cPhone = normPhone(c.cell_phone || c.home_phone || c.office_phone || '');
  const dobOk = !!wantedDob && cDob === wantedDob;
  const emailOk = !!wantedEmail && cEmail === wantedEmail;
  const phoneOk = !!wantedPhone && cPhone === wantedPhone;
  const allOk = dobOk && emailOk && phoneOk;
  if (allOk) passing.push(c);
  return { id: c.id, dob_match: dobOk, email_match: emailOk, phone_match: phoneOk, pass: allOk };
});

let match_outcome, match_reason, patient_id = null;
let candidates_summary = '';

if (passing.length === 1) {
  match_outcome = 'matched';
  match_reason = 'unique_strict_match';
  patient_id = passing[0].id;
} else if (candidates.length === 0) {
  match_outcome = 'manual_review';
  match_reason = 'no_candidates_from_search';
} else if (passing.length === 0) {
  match_outcome = 'manual_review';
  match_reason = 'no_candidate_passed_strict_filter';
  candidates_summary = scored.slice(0, 10).map((s) => 'id=' + s.id).join(';');
} else {
  match_outcome = 'manual_review';
  match_reason = 'ambiguous_match';
  candidates_summary = passing.map((p) => 'id=' + p.id).join(';');
}

return [{ json: { ...original, candidates_searched: candidates.length, passing_count: passing.length, candidates_summary, match_outcome, match_reason, patient_id } }];

// Generate doctor-friendly Consultation Intake PDF (pure JS, no external deps).
// Mirrors the Phase 3 visual approved by Jeff: blue header band + DrSnip wordmark,
// large centered patient name, optional spouse line, Age + Children + DOB stat
// tiles, tabular sections for each Consultation form screen, footer on every
// page. HIPAA-safe — assembled in-process, never sent to a third-party renderer.
const src = $('Parse & Normalize').first().json;
const resolved = $('Resolve Patient ID').first().json;
const sub = src.submission_full || {};
const patient = sub.patient || {};
const aboutYou = sub.aboutYou || {};
const rel = sub.relationship || {};
const kids = sub.children || {};
const fp = sub.familyPlanning || {};
const bc = sub.birthControl || {};
const mp = sub.medicalPersonal || {};
const er = sub.emergencyReferral || {};

const PAGE_W = 612, PAGE_H = 792;
const ML = 54, MR = 54, MT = 54, MB = 54;
const FOOTER_RESERVE = 36;
const CONTENT_W = PAGE_W - ML - MR;
const LABEL_W = 196, COL_GAP = 12;
const VALUE_W = CONTENT_W - LABEL_W - COL_GAP;
const LABEL_SIZE = 9, VALUE_SIZE = 10;
const LABEL_LINE_H = 12, VALUE_LINE_H = 13;
const ROW_PAD_V = 4, ROW_MIN_H = 20;
const BAND_H = 80;

const C = {
  brand: [0x0f / 255, 0x4c / 255, 0x81 / 255],
  text: [0.12, 0.16, 0.22],
  muted: [0.42, 0.47, 0.53],
  faint: [0.62, 0.66, 0.70],
  line: [0.86, 0.88, 0.91],
  separator: [0xe5 / 255, 0xe7 / 255, 0xeb / 255],
  tile: [0.96, 0.97, 0.98],
  white: [1, 1, 1]
};

function charW(ch, font) {
  if (ch === ' ') return 0.28;
  if (ch === 'i' || ch === 'l' || ch === 'I' || ch === '.' || ch === ',' || ch === ';' || ch === ':' || ch === '!' || ch === "'" || ch === '|') return 0.30;
  if (ch >= 'A' && ch <= 'Z') return font === 'F2' ? 0.70 : 0.66;
  if (ch >= 'a' && ch <= 'z') return font === 'F2' ? 0.56 : 0.51;
  if (ch >= '0' && ch <= '9') return 0.56;
  if (ch === '(' || ch === ')' || ch === '-' || ch === '/' || ch === '[' || ch === ']') return 0.33;
  return font === 'F2' ? 0.56 : 0.51;
}
function tw(s, font, size) {
  let w = 0;
  const str = String(s == null ? '' : s);
  for (let i = 0; i < str.length; i++) w += charW(str[i], font);
  return w * size;
}

function wrap(text, font, size, maxWidth) {
  const out = [];
  const lines = String(text == null ? '' : text).split('\n');
  for (const rawLine of lines) {
    const words = rawLine.split(/\s+/).filter(Boolean);
    if (words.length === 0) { out.push(''); continue; }
    let line = '';
    for (const word of words) {
      let parts = [word];
      if (tw(word, font, size) > maxWidth) {
        parts = [];
        let rest = word;
        while (rest.length > 0) {
          let cut = rest.length;
          while (cut > 0 && tw(rest.slice(0, cut), font, size) > maxWidth) cut--;
          if (cut === 0) cut = 1;
          parts.push(rest.slice(0, cut));
          rest = rest.slice(cut);
        }
      }
      for (const piece of parts) {
        const candidate = line ? line + ' ' + piece : piece;
        if (line && tw(candidate, font, size) > maxWidth) {
          out.push(line);
          line = piece;
        } else {
          line = candidate;
        }
      }
    }
    if (line) out.push(line);
  }
  return out.length ? out : [''];
}

function pdfEsc(s) {
  return String(s == null ? '' : s)
    .replace(/\\/g, '\\\\')
    .replace(/\(/g, '\\(')
    .replace(/\)/g, '\\)')
    .replace(/—/g, '\\227')
    .replace(/–/g, '\\226')
    .replace(/’/g, '\\222')
    .replace(/‘/g, '\\221')
    .replace(/“/g, '\\223')
    .replace(/”/g, '\\224')
    .replace(/·/g, '\\267')
    .replace(/•/g, '\\225')
    .replace(/[\r\n]+/g, ' ')
    .replace(/[-￿]/g, '?');
}

const pages = [];
let curOps = [];
let y = PAGE_H - MT;

function newPage() { pages.push(curOps); curOps = []; y = PAGE_H - MT; }
function ensure(needed) { if (y - needed < MB + FOOTER_RESERVE) newPage(); }
function emitText(text, x, yy, size, font, color) { curOps.push({ k: 't', text: text, x: x, y: yy, size: size, font: font, color: color }); }
function emitRect(x, yy, w, h, fill) { curOps.push({ k: 'r', x: x, y: yy, w: w, h: h, fill: fill }); }
function emitRectBorder(x, yy, w, h, fill, stroke) { curOps.push({ k: 'rb', x: x, y: yy, w: w, h: h, fill: fill, stroke: stroke }); }
function emitLine(x1, y1, x2, y2, color, width) { curOps.push({ k: 'l', x1: x1, y1: y1, x2: x2, y2: y2, color: color, width: width }); }

function renderHeader(opts) {
  const bandY = PAGE_H - BAND_H;
  emitRect(0, bandY, PAGE_W, BAND_H, C.brand);
  emitText('DrSnip', ML, bandY + BAND_H / 2 - 9, 22, 'F2', C.white);
  const badge = opts.formType === 'consultation' ? 'Consultation Intake' : 'Registration Intake';
  const bw = tw(badge, 'F2', 11);
  emitText(badge, PAGE_W - MR - bw, bandY + BAND_H / 2 - 5, 11, 'F2', C.white);

  y = bandY - 30;
  const nw = tw(opts.patientName, 'F2', 24);
  emitText(opts.patientName, (PAGE_W - nw) / 2, y - 24, 24, 'F2', C.text);
  y -= 24 + 6;

  if (opts.spouseName) {
    const sLabel = 'Spouse: ' + opts.spouseName;
    const sw = tw(sLabel, 'F3', 12);
    emitText(sLabel, (PAGE_W - sw) / 2, y - 12, 12, 'F3', C.muted);
    y -= 12 + 4;
  }
  y -= 16;

  const tiles = [{ label: 'AGE', value: opts.age != null ? String(opts.age) : '—' }];
  if (opts.formType === 'consultation') {
    tiles.push({ label: 'CHILDREN', value: opts.childCount != null ? String(opts.childCount) : '—' });
  }

  const TW = 156, TH = 56, TG = 16;
  const totalW = tiles.length * TW + (tiles.length - 1) * TG;
  let tx = (PAGE_W - totalW) / 2;
  const tileTop = y;
  for (const t of tiles) {
    emitRectBorder(tx, tileTop - TH, TW, TH, C.tile, C.line);
    const lw = tw(t.label, 'F1', 8);
    emitText(t.label, tx + (TW - lw) / 2, tileTop - 19, 8, 'F1', C.muted);
    const vw = tw(t.value, 'F2', 17);
    emitText(t.value, tx + (TW - vw) / 2, tileTop - 44, 17, 'F2', C.brand);
    tx += TW + TG;
  }
  y = tileTop - TH - 18;

  emitText('Submitted: ' + opts.submittedAt, ML, y - 9, 9, 'F1', C.muted);
  y -= 13;
  emitText('Submission ID: ' + opts.submissionId, ML, y - 8, 8, 'F1', C.faint);
  y -= 14;

  emitLine(ML, y, PAGE_W - MR, y, C.line, 0.75);
  y -= 8;
}

function heading(title) {
  y -= 10;
  ensure(30 + 2 * ROW_MIN_H);
  emitRect(ML, y - 13, 3, 13, C.brand);
  emitText(title, ML + 9, y - 12, 12, 'F2', C.brand);
  y -= 17;
  emitLine(ML, y, PAGE_W - MR, y, C.line, 0.75);
  y -= 10;
}

function row(label, value, valueFont, valueColor, omitRule) {
  const labelLines = wrap(label, 'F1', LABEL_SIZE, LABEL_W);
  const valueLines = wrap(value, valueFont, VALUE_SIZE, VALUE_W);
  const contentH = Math.max(labelLines.length * LABEL_LINE_H, valueLines.length * VALUE_LINE_H);
  const rowH = Math.max(contentH + ROW_PAD_V * 2, ROW_MIN_H);
  ensure(rowH);
  const top = y;
  const valueX = ML + LABEL_W + COL_GAP;
  let ly = top - ROW_PAD_V - LABEL_SIZE;
  for (const ln of labelLines) { emitText(ln, ML, ly, LABEL_SIZE, 'F1', C.muted); ly -= LABEL_LINE_H; }
  let vy = top - ROW_PAD_V - VALUE_SIZE;
  for (const ln of valueLines) { emitText(ln, valueX, vy, VALUE_SIZE, valueFont, valueColor); vy -= VALUE_LINE_H; }
  if (!omitRule) emitLine(ML, top - rowH, PAGE_W - MR, top - rowH, C.separator, 0.5);
  y = top - rowH;
}

function kv(label, value) {
  const trimmed = (value != null && String(value).trim()) ? String(value).trim() : '—';
  const isEmpty = trimmed === '—';
  row(label, trimmed, isEmpty ? 'F1' : 'F2', isEmpty ? C.faint : C.text, false);
}

function kvBool(label, value) {
  if (value === true) return kv(label, 'Yes');
  if (value === false) return kv(label, 'No');
  return kv(label, value);
}

function arrayRow(label, values) {
  const clean = (Array.isArray(values) ? values : []).map(function (v) { return v == null ? '' : String(v).trim(); }).filter(Boolean);
  if (clean.length === 0) return kv(label, '');
  const joined = clean.join(', ');
  let lines;
  if (joined.length <= 60) {
    lines = wrap(joined, 'F2', VALUE_SIZE, VALUE_W);
  } else {
    lines = [];
    for (const item of clean) {
      const ln = wrap('•  ' + item, 'F2', VALUE_SIZE, VALUE_W);
      for (const l of ln) lines.push(l);
    }
  }
  const labelLines = wrap(label, 'F1', LABEL_SIZE, LABEL_W);
  const contentH = Math.max(labelLines.length * LABEL_LINE_H, lines.length * VALUE_LINE_H);
  const rowH = Math.max(contentH + ROW_PAD_V * 2, ROW_MIN_H);
  ensure(rowH);
  const top = y;
  const valueX = ML + LABEL_W + COL_GAP;
  let ly = top - ROW_PAD_V - LABEL_SIZE;
  for (const ln of labelLines) { emitText(ln, ML, ly, LABEL_SIZE, 'F1', C.muted); ly -= LABEL_LINE_H; }
  let vy = top - ROW_PAD_V - VALUE_SIZE;
  for (const ln of lines) { emitText(ln, valueX, vy, VALUE_SIZE, 'F2', C.text); vy -= VALUE_LINE_H; }
  emitLine(ML, top - rowH, PAGE_W - MR, top - rowH, C.separator, 0.5);
  y = top - rowH;
}

function childrenBlock(children) {
  ensure(24);
  emitText('Children', ML, y - 10, 10, 'F2', C.text);
  y -= 10 + 4;
  if (!Array.isArray(children) || children.length === 0) {
    ensure(14);
    emitText('—', ML + 12, y - 10, 10, 'F1', C.faint);
    y -= 10 + 6;
    return;
  }
  const v = function (s) { return (s && String(s).trim()) ? String(s).trim() : '—'; };
  for (let i = 0; i < children.length; i++) {
    const c = children[i] || {};
    ensure(34);
    emitText('Child ' + (i + 1), ML + 12, y - 9, 9, 'F2', C.muted);
    y -= 9 + 4;
    const detail = 'Age ' + v(c.age) + '    ·    Relation: ' + v(c.relation) + '    ·    Gender: ' + v(c.gender);
    emitText(detail, ML + 24, y - 10, 10, 'F1', C.text);
    y -= 10 + 5;
    emitLine(ML, y, PAGE_W - MR, y, C.separator, 0.5);
    y -= 4;
  }
  y -= 2;
}

function calcAge(dob) {
  if (!dob) return null;
  const d = new Date(dob + 'T00:00:00');
  if (isNaN(d.getTime())) return null;
  const t = new Date();
  let a = t.getFullYear() - d.getFullYear();
  const m = t.getMonth() - d.getMonth();
  if (m < 0 || (m === 0 && t.getDate() < d.getDate())) a--;
  return a < 0 ? 0 : a;
}

const patientName = (((patient.firstName || '') + ' ' + (patient.lastName || '')).trim()) || '(Unknown Patient)';
const spouseName = (((rel.partnerFirstName || '') + ' ' + (rel.partnerLastName || '')).trim()) || null;
const childrenList = Array.isArray(kids.details) ? kids.details : [];
const childCount = (kids.count != null) ? Number(kids.count) : childrenList.length;
const submittedAt = ((src.timestamp || '').slice(0, 16).replace('T', ' ')) + ' UTC';

renderHeader({
  formType: 'consultation',
  patientName: patientName,
  spouseName: spouseName,
  age: calcAge(patient.dateOfBirth),
  childCount: childCount,
  dob: patient.dateOfBirth,
  submittedAt: submittedAt,
  submissionId: src.submission_id || ''
});

heading('About You');
kv('First Name', patient.firstName);
kv('Last Name', patient.lastName);
kv('Email', patient.email);
kv('Phone Number', patient.phone);
kv('Date of Birth', patient.dateOfBirth);
kv('Field of Work / Occupation', aboutYou.occupation);
kv('Employer', aboutYou.employer);
kv('Job Title', aboutYou.jobTitle);
kv('Job Demands', aboutYou.jobDemands);

heading('Relationship');
kv('Relationship Status', rel.status);
kv('Relationship status — please specify', rel.statusOther);
kv("Partner / Spouse's First Name", rel.partnerFirstName);
kv("Partner / Spouse's Last Name", rel.partnerLastName);
kv("Partner / Spouse's Phone", rel.partnerPhone);
kvBool('Consent to share information with the partner if they contact us directly', rel.partnerShareConsent);
kv("Partner / Spouse's Age", rel.partnerAge);
kv("Partner / Spouse's Field of Work", rel.partnerOccupation);
kv("Partner / Spouse's Education", rel.partnerEducation);
kv('Years in this relationship', rel.yearsInRelationship);
kv('Which marriage is this for you?', rel.marriageNumberSelf);
kv('Which marriage is this for your spouse?', rel.marriageNumberSpouse);

heading('Children');
kv('How many children do you have?', String(childCount));
childrenBlock(childrenList);

heading('Family Planning');
kv('Do you wish to have more children in the future?', fp.wantMoreChildren);
kv('Would you consider adoption if you chose to have more children?', fp.considerAdoption);
kv('For how long have you considered a vasectomy?', fp.vasectomyConsideredDuration);
kv('Have you considered tubal ligation as an alternative sterilization choice?', bc.consideredTubal);
kv('Have you considered temporary birth control methods (condoms, diaphragm, etc.)?', bc.consideredTemporaryBC);

heading('Birth Control');
arrayRow('Current birth control methods', bc.currentBC);
kv('Other current birth control methods', bc.currentBCOther);
arrayRow('Prior methods of birth control', bc.priorBC);

heading('Medical & Personal Considerations');
kv('Does a vasectomy conflict with your religion?', mp.religionConflict);
if (mp.religionConflictDetails) kv('Religion conflict — details', mp.religionConflictDetails);
kv('Do you, or does your partner, have any sexual problems or concerns?', mp.sexualConcerns);
kv('Sexual problems or concerns — details', mp.sexualConcernsDetails);
kv('Are you choosing sterilization because of a genetic condition concerning you or your partner?', mp.geneticCondition);
kv('Genetic condition — details', mp.geneticConditionDetails);

const movedMedical = sub.medicalHistory || {};
const mhAns = function (k) { return (movedMedical[k] && movedMedical[k].answer) || ''; };
const mhDet = function (k) { return (movedMedical[k] && movedMedical[k].details) || ''; };
kv('Does mental illness or depression affect your decision making?', mhAns('mhMentalIllness'));
if (mhDet('mhMentalIllness')) kv('Please share details, including a general timeframe.', mhDet('mhMentalIllness'));
kv('Do you think you are more sensitive to pain than the average person?', mhAns('mhPainSensitive'));
if (mhDet('mhPainSensitive')) kv('Please share details.', mhDet('mhPainSensitive'));
kv('Have you ever fainted during, or after, a medical procedure?', mhAns('mhFainting'));
if (mhDet('mhFainting')) kv('Please share details.', mhDet('mhFainting'));

heading('Emergency Contact & Referral');
kv('Emergency Contact Name', er.name);
kv('Emergency Contact Phone Number', er.phone);
kv('Emergency Contact Relationship', er.relationship);
kv('How did you hear about DrSnip?', er.howHeard);
kv('How did you hear about DrSnip — please specify', er.howHeardOther);
kv('Referring medical professional (name and specialty)', er.referringProfessional);
kv("Is there anything else you'd like to share with DrSnip before your appointment?", er.additionalNotes);

if (curOps.length) { pages.push(curOps); curOps = []; }

const totalPages = pages.length;
const subId = src.submission_id || '';
for (let idx = 0; idx < pages.length; idx++) {
  const ops = pages[idx];
  const fy = 30;
  ops.push({ k: 'l', x1: ML, y1: fy + 12, x2: PAGE_W - MR, y2: fy + 12, color: C.line, width: 0.5 });
  const left = (patientName && patientName !== '(Unknown Patient)') ? (patientName + ' · CONFIDENTIAL / PHI') : 'DrSnip Patient Intake — CONFIDENTIAL / PHI';
  const center = 'Page ' + (idx + 1) + ' of ' + totalPages;
  const right = 'Submission ' + subId;
  const cw = tw(center, 'F1', 7);
  const rw = tw(right, 'F1', 7);
  ops.push({ k: 't', text: left, x: ML, y: fy, size: 7, font: 'F1', color: C.faint });
  ops.push({ k: 't', text: center, x: (PAGE_W - cw) / 2, y: fy, size: 7, font: 'F1', color: C.faint });
  ops.push({ k: 't', text: right, x: PAGE_W - MR - rw, y: fy, size: 7, font: 'F1', color: C.faint });
}

function fmtColor(c) { return c[0].toFixed(3) + ' ' + c[1].toFixed(3) + ' ' + c[2].toFixed(3); }
function renderOps(ops) {
  let s = '';
  let curFill = null, curStroke = null, curLW = null;
  for (const op of ops) {
    if (op.k === 't') {
      const key = op.color.join(',');
      if (key !== curFill) { s += fmtColor(op.color) + ' rg\n'; curFill = key; }
      s += 'BT /' + op.font + ' ' + op.size + ' Tf ' + op.x.toFixed(2) + ' ' + op.y.toFixed(2) + ' Td (' + pdfEsc(op.text) + ') Tj ET\n';
    } else if (op.k === 'r') {
      const key = op.fill.join(',');
      if (key !== curFill) { s += fmtColor(op.fill) + ' rg\n'; curFill = key; }
      s += op.x.toFixed(2) + ' ' + op.y.toFixed(2) + ' ' + op.w.toFixed(2) + ' ' + op.h.toFixed(2) + ' re f\n';
    } else if (op.k === 'rb') {
      const fk = op.fill.join(',');
      if (fk !== curFill) { s += fmtColor(op.fill) + ' rg\n'; curFill = fk; }
      const sk = op.stroke.join(',');
      if (sk !== curStroke) { s += fmtColor(op.stroke) + ' RG\n'; curStroke = sk; }
      if (curLW !== 1) { s += '1 w\n'; curLW = 1; }
      s += op.x.toFixed(2) + ' ' + op.y.toFixed(2) + ' ' + op.w.toFixed(2) + ' ' + op.h.toFixed(2) + ' re B\n';
    } else if (op.k === 'l') {
      const sk = op.color.join(',');
      if (sk !== curStroke) { s += fmtColor(op.color) + ' RG\n'; curStroke = sk; }
      if (curLW !== op.width) { s += op.width + ' w\n'; curLW = op.width; }
      s += op.x1.toFixed(2) + ' ' + op.y1.toFixed(2) + ' m ' + op.x2.toFixed(2) + ' ' + op.y2.toFixed(2) + ' l S\n';
    }
  }
  return s;
}

const objects = [];
function addObj(s) { objects.push(s); return objects.length; }
const catalogId = addObj('PLACEHOLDER');
const pagesId = addObj('PLACEHOLDER');
const helvId = addObj('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>');
const helvBoldId = addObj('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>');
const helvOblId = addObj('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Oblique /Encoding /WinAnsiEncoding >>');

const pageIds = [];
for (const ops of pages) {
  const stream = renderOps(ops);
  const len = Buffer.byteLength(stream, 'binary');
  const streamId = addObj('<< /Length ' + len + ' >>\nstream\n' + stream + 'endstream');
  const pageObj = '<< /Type /Page /Parent ' + pagesId + ' 0 R /MediaBox [0 0 ' + PAGE_W + ' ' + PAGE_H + '] /Resources << /Font << /F1 ' + helvId + ' 0 R /F2 ' + helvBoldId + ' 0 R /F3 ' + helvOblId + ' 0 R >> >> /Contents ' + streamId + ' 0 R >>';
  pageIds.push(addObj(pageObj));
}
objects[catalogId - 1] = '<< /Type /Catalog /Pages ' + pagesId + ' 0 R >>';
objects[pagesId - 1] = '<< /Type /Pages /Count ' + pageIds.length + ' /Kids [' + pageIds.map(function (i) { return i + ' 0 R'; }).join(' ') + '] >>';

let pdf = '%PDF-1.4\n%\xE2\xE3\xCF\xD3\n';
const offsets = [];
for (let i = 0; i < objects.length; i++) {
